"use client"

import React, { Fragment, useState } from 'react'
import Link from 'next/link'
import Pageheader from '@/shared/layout-components/page-header/pageheader'
import Seo from '@/shared/layout-components/seo/seo'
import {
  getModuleById,
  getCurriculumForModule,
  type TrainingModule,
  type CurriculumSection,
} from '../data'

function CourseBanner({ course }: { course: TrainingModule }) {
  return (
    <div className="relative -mx-4 sm:-mx-6 lg:-mx-8 -mt-4 sm:-mt-6 lg:-mt-8 mb-8">
      <div className="relative h-64 sm:h-72 md:h-80 lg:h-96 overflow-hidden">
        <img
          src={course.coverImage}
          alt=""
          className="w-full h-full object-cover"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/50 to-transparent" />
        <div className="absolute bottom-0 left-0 right-0 p-4 sm:p-6 lg:p-8 text-white">
          <div className="max-w-4xl">
            <span className="text-xs sm:text-sm font-medium text-white/80 uppercase tracking-wide">
              {course.categoryName}
            </span>
            <h1 className="text-2xl sm:text-3xl md:text-4xl font-bold mt-1 leading-tight">
              {course.name}
            </h1>
            <p className="text-sm sm:text-base text-white/90 mt-2 line-clamp-2 max-w-2xl">
              {course.shortDescription}
            </p>
            <div className="flex flex-wrap items-center gap-3 sm:gap-5 mt-4 text-sm text-white/90">
              <span className="inline-flex items-center gap-1.5">
                <i className="ri-user-line text-lg" />
                {course.studentsEnrolled} students enrolled
              </span>
              {course.durationHours != null && (
                <span className="inline-flex items-center gap-1.5">
                  <i className="ri-time-line text-lg" />
                  {course.durationHours} total hours
                </span>
              )}
              {course.level && (
                <span className="inline-flex items-center gap-1.5">
                  <i className="ri-bar-chart-line text-lg" />
                  {course.level}
                </span>
              )}
              {course.language && (
                <span className="inline-flex items-center gap-1.5">
                  <i className="ri-global-line text-lg" />
                  {course.language}
                </span>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

function CurriculumSectionBlock({
  section,
  defaultOpen = false,
}: {
  section: CurriculumSection
  defaultOpen?: boolean
}) {
  const [open, setOpen] = useState(defaultOpen)
  const iconMap = {
    video: 'ri-play-circle-line',
    pdf: 'ri-file-pdf-line',
    blog: 'ri-article-line',
    quiz: 'ri-questionnaire-line',
    test: 'ri-file-list-3-line',
  }
  return (
    <div className="border border-defaultborder rounded-lg overflow-hidden bg-bodybg">
      <button
        type="button"
        onClick={() => setOpen(!open)}
        className="w-full flex items-center justify-between p-4 text-left font-semibold hover:bg-black/5 dark:hover:bg-white/5 transition-colors"
      >
        <span>{section.title}</span>
        <span className="text-[#8c9097] dark:text-white/50 text-sm font-normal">
          {section.lessons.length} lesson{section.lessons.length !== 1 ? 's' : ''}
        </span>
        <i className={`ri-arrow-down-s-line text-xl transition-transform ${open ? 'rotate-180' : ''}`} />
      </button>
      {open && (
        <ul className="border-t border-defaultborder divide-y divide-defaultborder">
          {section.lessons.map((lesson, idx) => (
            <li key={lesson.id} className="flex items-center gap-3 px-4 py-3 hover:bg-black/5 dark:hover:bg-white/5">
              <span className="flex items-center justify-center w-8 h-8 rounded-full bg-primary/10 text-primary text-sm font-medium">
                {idx + 1}
              </span>
              <i className={`${iconMap[lesson.type]} text-[#8c9097] dark:text-white/50 text-lg`} />
              <div className="flex-1 min-w-0">
                <span className="font-medium text-[0.9375rem]">{lesson.title}</span>
                {lesson.duration && (
                  <span className="text-[0.75rem] text-[#8c9097] dark:text-white/50 ml-2">
                    {lesson.duration}
                  </span>
                )}
              </div>
              <i className="ri-lock-line text-[#8c9097] dark:text-white/50" />
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

export default function CourseDetailView({ id }: { id: string }) {
  const course = id ? getModuleById(id) : undefined
  const curriculum = course ? getCurriculumForModule(course.id) : []

  if (!course) {
    return (
      <Fragment>
        <Seo title="Course not found" />
        <Pageheader currentpage="Course" activepage="Training Curriculum" mainpage="Course" />
        <div className="box custom-box text-center py-12">
          <p className="text-[#8c9097] dark:text-white/50 mb-4">Course not found.</p>
          <Link href="/training/curriculum/modules" className="ti-btn ti-btn-primary-full">
            Back to Modules
          </Link>
        </div>
      </Fragment>
    )
  }

  return (
    <Fragment>
      <Seo title={course.name} />
      <Pageheader
        currentpage={course.name}
        activepage="Training Curriculum"
        mainpage="Training Modules"
      />

      <CourseBanner course={course} />

      <div className="grid grid-cols-12 gap-6 lg:gap-8">
        <div className="lg:col-span-8 col-span-12 space-y-8">
          <section>
            <h2 className="text-xl font-bold text-defaulttextcolor mb-4">About this course</h2>
            <p className="text-[#8c9097] dark:text-white/70 leading-relaxed">
              {course.shortDescription}
            </p>
          </section>

          <section>
            <h2 className="text-xl font-bold text-defaulttextcolor mb-4">Curriculum</h2>
            <p className="text-[0.8125rem] text-[#8c9097] dark:text-white/50 mb-4">
              {curriculum.reduce((acc, s) => acc + s.lessons.length, 0)} lessons across{' '}
              {curriculum.length} section{curriculum.length !== 1 ? 's' : ''}
            </p>
            <div className="space-y-3">
              {curriculum.map((sec, idx) => (
                <CurriculumSectionBlock key={sec.id} section={sec} defaultOpen={idx === 0} />
              ))}
            </div>
          </section>
        </div>

        <div className="lg:col-span-4 col-span-12">
          <div className="sticky top-4">
            <div className="box custom-box border border-defaultborder overflow-hidden">
              <div className="relative h-40 overflow-hidden">
                <img
                  src={course.coverImage}
                  alt=""
                  className="w-full h-full object-cover"
                />
                <div className="absolute inset-0 bg-black/30" />
              </div>
              <div className="p-4">
                <div className="flex flex-wrap gap-2 mb-4">
                  <span className="inline-flex items-center gap-1 px-2 py-1 rounded bg-primary/10 text-primary text-[0.75rem]">
                    <i className="ri-video-line" />
                    {course.summary.videos} videos
                  </span>
                  <span className="inline-flex items-center gap-1 px-2 py-1 rounded bg-primary/10 text-primary text-[0.75rem]">
                    <i className="ri-file-pdf-line" />
                    {course.summary.pdfs} PDFs
                  </span>
                  <span className="inline-flex items-center gap-1 px-2 py-1 rounded bg-primary/10 text-primary text-[0.75rem]">
                    <i className="ri-questionnaire-line" />
                    {course.summary.quiz} quizzes
                  </span>
                </div>
                <Link
                  href="/training/curriculum/modules"
                  className="ti-btn ti-btn-light w-full !mb-0"
                >
                  <i className="ri-arrow-left-line me-1" />
                  Back to Modules
                </Link>
              </div>
            </div>

            <div className="box custom-box mt-4">
              <div className="box-header">
                <div className="box-title text-[0.9375rem]">Instructors</div>
              </div>
              <div className="box-body p-0">
                <ul className="divide-y divide-defaultborder">
                  {course.mentors.map((mentor) => (
                    <li key={mentor.id} className="flex items-center gap-3 p-4">
                      <img
                        src={mentor.avatar}
                        alt={mentor.name}
                        className="w-12 h-12 rounded-full object-cover"
                      />
                      <div>
                        <div className="font-semibold text-defaulttextcolor">{mentor.name}</div>
                        <div className="text-[0.75rem] text-[#8c9097] dark:text-white/50">
                          Instructor
                        </div>
                      </div>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        </div>
      </div>
    </Fragment>
  )
}
